#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 0x400
static char main_out[OUT_BUF_SIZE];

static void to_camel(const char *src) {
    size_t out = 0;
    int cap = 0;
    for (size_t i = 0; src[i] && out + 1 < OUT_BUF_SIZE; ++i) {
        char ch = src[i];
        if (ch == '_') { cap = 1; continue; }
        if (cap && ch >= 'a' && ch <= 'z') ch = ch - ('a' - 'A');
        main_out[out++] = ch;
        cap = 0;
    }
    main_out[out] = '\0';
}

static void to_snake(const char *src) {
    size_t out = 0;
    for (size_t i = 0; src[i] && out + 1 < OUT_BUF_SIZE; ++i) {
        char ch = src[i];
        if (ch >= 'A' && ch <= 'Z') {
            if (out + 2 >= OUT_BUF_SIZE) break; // need space for '_' and lower case char
            main_out[out++] = '_';
            ch = ch + ('a' - 'A');
        }
        main_out[out++] = ch;
    }
    main_out[out] = '\0';
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
        puts(main_out);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
        puts(main_out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
